import pytest

from pharmagene.config import Settings
from pharmagene.kg import GenotypeError, Lexicon, parse_genotypes, resolve

LEX = Lexicon.from_dir(Settings().kb_dir)

NM, IM, PM = "Normal Metabolizer", "Intermediate Metabolizer", "Poor Metabolizer"
RM, UM = "Rapid Metabolizer", "Ultrarapid Metabolizer"

# Expected values written by hand from the CPIC translation tables (not generated by the code).
TRUTH = [
    ("CYP2C19", "*1/*1", NM), ("CYP2C19", "*1/*17", RM), ("CYP2C19", "*17/*17", UM),
    ("CYP2C19", "*1/*2", IM), ("CYP2C19", "*1/*3", IM), ("CYP2C19", "*2/*17", IM),
    ("CYP2C19", "*2/*2", PM), ("CYP2C19", "*2/*3", PM), ("CYP2C19", "*3/*3", PM),
    ("TPMT", "*1/*1", NM), ("TPMT", "*1/*3A", IM), ("TPMT", "*3A/*3C", PM), ("TPMT", "*3C/*4", PM),
    ("DPYD", "*1/*1", NM), ("DPYD", "*1/*2A", IM), ("DPYD", "*2A/*2A", PM),
    ("DPYD", "*1/c.2846A>T", IM), ("DPYD", "c.2846A>T/c.2846A>T", IM), ("DPYD", "*2A/c.2846A>T", PM),
    ("DPYD", "*1/HapB3", IM),
    ("CYP2D6", "*1/*1", NM), ("CYP2D6", "*1/*4", IM), ("CYP2D6", "*4/*4", PM), ("CYP2D6", "*4/*5", PM),
    ("CYP2D6", "*1/*10", NM), ("CYP2D6", "*10/*10", IM), ("CYP2D6", "*2/*41", NM),
    ("CYP2D6", "*1xN/*1", UM), ("CYP2D6", "*2x2/*1", UM),
    ("SLCO1B1", "*1/*1", "Normal Function"), ("SLCO1B1", "*1/*5", "Decreased Function"),
    ("SLCO1B1", "*5/*5", "Poor Function"), ("SLCO1B1", "*5/*15", "Poor Function"),
    ("SLCO1B1", "c.521T>C (heterozygous)", "Decreased Function"),
    ("SLCO1B1", "c.521T>C homozygous", "Poor Function"),
]


@pytest.mark.parametrize("gene,genotype,expected", TRUTH)
def test_translation_matches_cpic(gene, genotype, expected):
    res = resolve(LEX.genes[gene], genotype)
    assert res.phenotype == expected
    assert not res.ambiguous


def test_explanations_never_mention_a_different_phenotype():
    """The KG explanation is cited as evidence, so it must pass the verifier's phenotype check."""
    from itertools import combinations_with_replacement

    for gene in LEX.genes.values():
        for a, b in combinations_with_replacement(gene.alleles, 2):
            try:
                res = resolve(gene, f"{a}/{b}")
            except GenotypeError:
                continue
            mentioned = set(LEX.phenotypes_in(res.explanation))
            assert mentioned <= set(res.phenotypes), (gene.symbol, a, b, res.explanation)


def test_duplication_changes_phenotype_but_text_barely_does():
    normal = resolve(LEX.genes["CYP2D6"], "*1/*1")
    dup = resolve(LEX.genes["CYP2D6"], "*1xN/*1")
    assert normal.activity_score == 2.0 and normal.phenotype == "Normal Metabolizer"
    assert dup.activity_score == 3.0 and dup.activity_lower_bound
    assert dup.phenotype == "Ultrarapid Metabolizer"


def test_unspecified_copy_number_can_be_ambiguous():
    res = resolve(LEX.genes["CYP2D6"], "*1xN/*4")
    assert res.ambiguous and res.phenotype is None
    assert set(res.phenotypes) == {"Normal Metabolizer", "Ultrarapid Metabolizer"}


def test_allele_names_are_case_insensitive_and_normalized():
    res = resolve(LEX.genes["TPMT"], "*1/*3a")
    assert res.genotype == "*1/*3A" and res.phenotype == "Intermediate Metabolizer"


@pytest.mark.parametrize(
    "gene,genotype,kind",
    [
        ("CYP2C19", "*99/*2", "invalid_allele"),
        ("CYP2C19", "*2", "incomplete"),
        ("SLCO1B1", "c.521T>C", "incomplete"),
        ("CYP2C19", "*1xN/*2", "unsupported"),
        ("CYP2C19", "banana/*2", "invalid_allele"),
    ],
)
def test_errors_are_explicit(gene, genotype, kind):
    with pytest.raises(GenotypeError) as exc:
        resolve(LEX.genes[gene], genotype)
    assert exc.value.kind == kind


def test_parse_multi_gene_text():
    assert parse_genotypes("CYP2C19 *2/*2; DPYD *1/*2A", LEX) == {"CYP2C19": "*2/*2", "DPYD": "*1/*2A"}
    assert parse_genotypes("CYP2C19*2/*2 and TPMT *1 / *3A", LEX) == {"CYP2C19": "*2/*2", "TPMT": "*1/*3A"}


def test_parse_single_variant_with_zygosity():
    got = parse_genotypes("Patient carries the SLCO1B1 c.521T>C variant (heterozygous) on simvastatin.", LEX)
    assert got == {"SLCO1B1": "c.521T>C (heterozygous)"}


def test_parse_ignores_text_without_genotype():
    assert parse_genotypes("Patient needs simvastatin for hyperlipidemia.", LEX) == {}


def test_lexicon_links_aliases_and_phenotypes():
    assert LEX.find_drugs("Started Plavix and 5-FU last week") == ["clopidogrel", "fluorouracil"]
    assert set(LEX.phenotypes_in("ultra-rapid metabolizers and poor metabolizers")) == {
        "Poor Metabolizer", "Ultrarapid Metabolizer"
    }
    assert LEX.phenotypes_in("rapid metabolizer") == ["Rapid Metabolizer"]
